import os
from typing import List, Dict, Any

import requests


class ContentSafetyClient:
    """
    Uses Azure AI Content Safety hosted API to detect unsafe content and redact flagged spans.
    Requires:
      - AZURE_CONTENT_SAFETY_ENDPOINT, e.g. https://<resource-name>.cognitiveservices.azure.com
      - AZURE_CONTENT_SAFETY_KEY
    """

    def __init__(self, endpoint: str = None, api_key: str = None, api_version: str = "2023-10-15-preview"):
        self.endpoint = (endpoint or os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT") or "").rstrip("/")
        self.api_key = api_key or os.environ.get("AZURE_CONTENT_SAFETY_KEY") or ""
        self.api_version = api_version
        if not self.endpoint or not self.api_key:
            raise ValueError("Missing AZURE_CONTENT_SAFETY_ENDPOINT or AZURE_CONTENT_SAFETY_KEY")

    def analyze_text(self, text: str) -> Dict[str, Any]:
        url = f"{self.endpoint}/contentsafety/text:analyze?api-version={self.api_version}"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/json",
        }
        payload = {
            "text": text,
            "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
            "outputType": "FourSeverityLevels",
        }
        resp = requests.post(url, headers=headers, json=payload, timeout=30)
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _severity_is_unsafe(severity: int, threshold: int = 2) -> bool:
        return severity is not None and severity >= threshold

    def _extract_unsafe_spans(self, text: str, analysis: Dict[str, Any], threshold: int = 2) -> List[Dict[str, Any]]:
        spans: List[Dict[str, Any]] = []
        cats = analysis.get("categoriesAnalysis", []) or []
        for cat in cats:
            severity = cat.get("severity")
            if not self._severity_is_unsafe(severity, threshold=threshold):
                continue

            # Azure Content Safety text analyze returns optional "text" insight only in some configurations;
            # if offsets are present, redact them; otherwise flag the whole text for that category.
            if "offset" in cat and "length" in cat:
                spans.append(
                    {
                        "category": cat.get("category", "Unknown"),
                        "severity": severity,
                        "start": int(cat["offset"]),
                        "end": int(cat["offset"]) + int(cat["length"]),
                    }
                )
            else:
                spans.append(
                    {
                        "category": cat.get("category", "Unknown"),
                        "severity": severity,
                        "start": 0,
                        "end": len(text),
                    }
                )
        return spans

    @staticmethod
    def _merge_spans(spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []
        spans = sorted(spans, key=lambda s: (s["start"], s["end"]))
        merged = [spans[0].copy()]
        for span in spans[1:]:
            last = merged[-1]
            if span["start"] <= last["end"]:
                last["end"] = max(last["end"], span["end"])
                last["category"] = ",".join(sorted(set((last.get("category", "") + "," + span.get("category", "")).split(",")) - {""}))
                last["severity"] = max(int(last.get("severity", 0)), int(span.get("severity", 0)))
            else:
                merged.append(span.copy())
        return merged

    def flag_unsafe_spans(self, text: str, threshold: int = 2) -> List[Dict[str, Any]]:
        analysis = self.analyze_text(text)
        spans = self._extract_unsafe_spans(text, analysis, threshold=threshold)
        return self._merge_spans(spans)

    def redact_unsafe_spans(self, text: str, threshold: int = 2, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        spans = self.flag_unsafe_spans(text, threshold=threshold)
        if not spans:
            return {"text": text, "spans": [], "redacted": False}

        out = []
        cursor = 0
        for span in spans:
            start = max(0, min(len(text), span["start"]))
            end = max(0, min(len(text), span["end"]))
            if start > cursor:
                out.append(text[cursor:start])
            out.append(replacement)
            cursor = max(cursor, end)
        if cursor < len(text):
            out.append(text[cursor:])

        return {"text": "".join(out), "spans": spans, "redacted": True}


def flag_unsafe_spans(text: str, threshold: int = 2) -> List[Dict[str, Any]]:
    return ContentSafetyClient().flag_unsafe_spans(text, threshold=threshold)


def redact_unsafe_spans(text: str, threshold: int = 2, replacement: str = "[REDACTED]") -> Dict[str, Any]:
    return ContentSafetyClient().redact_unsafe_spans(text, threshold=threshold, replacement=replacement)
